// Pseudo-C implementation sketch for read_with_signal
int read_with_signal(int fd, void *buf, int n, int *interrupted){
  int total = 0;
  while (total < n){
    int got = kernel_read(fd, (char*)buf + total, n - total);
    if (got > 0){ total += got; continue; }
    if (pending_signal(fd_thread_id)){ *interrupted = 1; return -1; }
    // block until wake
  }
  return total;
}
